public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(CustTable, CustGroup) :
            info("Customer  group modified.");
            break;
    }
}

public void update(boolean _updateSmmBusRelTable, boolean _updateParty)
{
    next update(_updateSmmBusRelTable, _updateParty);

    CustTrans custTrans;

    ttsbegin;

    update_recordset custTrans
        setting MZNAGComment = this.MZNAGComment
        where custTrans.AccountNum == this.AccountNum;

    ttscommit;

}
